#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe smtp-serve-two-mail-domains. Do not edit.
set -e
cd "$(dirname "$0")"
cat > one.eml <<'EOF'
From: noreply@one.test
To: ann@one.test
Subject: Welcome to One

Thanks for joining One.
EOF
cat > two.eml <<'EOF'
From: noreply@two.test
To: ann@two.test
Subject: Welcome to Two

Thanks for joining Two.
EOF
cat > wait-log.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Usage: sh wait-log.sh TEXT LOG. Waits, a second at a time for at most 10, until LOG has a line
# holding TEXT, then prints those lines without their exchange number.
tries=0
until grep -q -e "$1" "$2"; do
  tries=$((tries + 1))
  if [ "$tries" -gt 10 ]; then echo "no line with $1 in $2" >&2; exit 1; fi
  sleep 1
done
grep -e "$1" "$2" | sed 's/^#[0-9]* //' | tr -d '\r'
EOF
surl -v --log-file surl.log --mail-domain one.test --mail-domain two.test --mailbox noreply@one.test:onepass --mailbox noreply@two.test:twopass --mailbox ann@one.test:annone --mailbox ann@two.test:anntwo --mailbox bo@one.test:boone --mailbox bo@two.test:botwo smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ &
sleep 1
curl -sS --crlf -u noreply@one.test:onepass --mail-from noreply@one.test --mail-rcpt ann@one.test -T one.eml smtp://127.0.0.1:8080/one.test --next -sS --crlf -u noreply@two.test:twopass --mail-from noreply@two.test --mail-rcpt ann@two.test -T two.eml smtp://127.0.0.1:8080/two.test --next -sS --retry 10 --retry-all-errors --retry-delay 1 -u ann@one.test:annone "imap://127.0.0.1:8081/INBOX;UID=1;SECTION=HEADER.FIELDS%20(SUBJECT)" --next -sS --retry 10 --retry-all-errors --retry-delay 1 -u ann@two.test:anntwo "imap://127.0.0.1:8081/INBOX;UID=1;SECTION=HEADER.FIELDS%20(SUBJECT)"
kill $(jobs -p)
